    <DesignCanvas>
      <DCSection id="main" title="Main">
        <DCArtboard id="web-desktop" label="Web desktop" kind="web" width={1440} height={900}></DCArtboard>
        <DCArtboard id="web-tablet" label="Web tablet" kind="web" width={834} height={1024}></DCArtboard>
        <DCArtboard id="web-mobile" label="Web mobile" kind="web" width={390} height={844}></DCArtboard>
      </DCSection>
    </DesignCanvas>
  );
}

