/*
 * Landing page.css — a small Brno coffee roastery.
 * opt_out_scope = palette: the `rb-` namespace swaps in a roastery palette
 * (warm paper, roasted brown, one terracotta accent). Type, spacing, radii
 * and motion stay the maude DS tokens.
 */

.rb {
  --rb-paper: oklch(0.965 0.012 75);
  --rb-paper-2: oklch(0.925 0.02 70);
  --rb-roast: oklch(0.27 0.03 45);
  --rb-roast-2: oklch(0.35 0.04 45);
  --rb-ink: oklch(0.24 0.02 45);
  --rb-ink-2: oklch(0.42 0.025 50);
  --rb-on-roast: oklch(0.95 0.015 75);
  --rb-on-roast-2: oklch(0.8 0.02 70);
  --rb-accent: oklch(0.56 0.14 40);
  --rb-accent-text: oklch(0.48 0.13 40);
  --rb-line: oklch(0.85 0.02 70);
  --rb-line-roast: oklch(0.42 0.03 45);

  position: absolute;
  inset: 0;
  overflow: auto;
  container-type: inline-size;
  background: var(--rb-paper);
  color: var(--rb-ink);
  font-family: var(--font-body);
  font-size: var(--type-md);
  line-height: var(--lh-md);
}

.rb-wrap { max-width: 1200px; margin: 0 auto; padding: 0 var(--space-7); }

/* ── nav ───────────────────────────────────────────────────────────────────── */
.rb-nav { display: flex; align-items: center; justify-content: space-between; gap: var(--space-5); padding: var(--space-5) 0; border-bottom: 1px solid var(--rb-line); }
.rb-brand { display: flex; align-items: center; gap: var(--space-3); color: var(--rb-ink); text-decoration: none; font-family: var(--font-display); font-weight: var(--weight-semibold); font-size: var(--type-lg); letter-spacing: var(--tracking-tight); }
.rb-links { display: flex; gap: var(--space-6); list-style: none; margin: 0; padding: 0; }
.rb-links a { color: var(--rb-ink-2); text-decoration: none; font-size: var(--type-base); }
.rb-btn { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; padding: 0 var(--space-5); border-radius: var(--radius-pill); font-weight: var(--weight-medium); font-size: var(--type-base); text-decoration: none; border: 1px solid transparent; }
.rb-btn--solid { background: var(--rb-roast); color: var(--rb-on-roast); }
.rb-btn--accent { background: var(--rb-accent); color: var(--rb-on-roast); }
.rb-btn--ghost { border-color: var(--rb-ink); color: var(--rb-ink); }
.rb-btn--ghost-light { border-color: var(--rb-on-roast-2); color: var(--rb-on-roast); }
.rb a:focus-visible { outline: var(--focus-ring-width) solid var(--rb-accent); outline-offset: var(--focus-ring-offset); }

/* ── hero ──────────────────────────────────────────────────────────────────── */
.rb-hero { display: grid; grid-template-columns: 1.1fr 1fr; gap: var(--space-8); align-items: center; padding: 96px 0 104px; }
.rb-eyebrow { font-family: var(--font-mono); font-size: var(--type-sm); letter-spacing: var(--tracking-wide); text-transform: uppercase; color: var(--rb-accent-text); margin: 0 0 var(--space-4); }
.rb-h1 { font-family: var(--font-display); font-weight: var(--weight-semibold); font-size: 72px; line-height: 1.02; letter-spacing: -0.03em; margin: 0 0 var(--space-5); text-wrap: balance; }
.rb-lead { font-size: var(--type-lg); line-height: var(--lh-lg); color: var(--rb-ink-2); max-width: 34em; margin: 0 0 var(--space-6); }
.rb-actions { display: flex; flex-wrap: wrap; gap: var(--space-3); }

.rb-plate { position: relative; aspect-ratio: 1; border-radius: 50%; background: var(--rb-roast); display: grid; place-items: center; box-shadow: inset 0 0 0 14px var(--rb-roast-2); }
.rb-plate svg { width: 78%; height: auto; }
.rb-stamp { position: absolute; right: -4%; bottom: 6%; width: 132px; height: 132px; border-radius: 50%; background: var(--rb-accent); color: var(--rb-on-roast); display: grid; place-items: center; text-align: center; font-family: var(--font-mono); font-size: var(--type-xs); letter-spacing: var(--tracking-wide); text-transform: uppercase; line-height: 1.35; transform: rotate(-10deg); }
.rb-stamp strong { display: block; font-family: var(--font-display); font-size: 30px; letter-spacing: -0.02em; text-transform: none; }

/* ── sections ──────────────────────────────────────────────────────────────── */
.rb-section { padding: 96px 0; }
.rb-section--alt { background: var(--rb-paper-2); }
.rb-section--roast { background: var(--rb-roast); color: var(--rb-on-roast); }
.rb-head { display: flex; justify-content: space-between; align-items: end; gap: var(--space-6); margin-bottom: var(--space-7); }
.rb-h2 { font-family: var(--font-display); font-weight: var(--weight-semibold); font-size: 44px; line-height: 1.08; letter-spacing: -0.02em; margin: 0; text-wrap: balance; }
.rb-sub { color: var(--rb-ink-2); max-width: 30em; margin: 0; }
.rb-section--roast .rb-sub { color: var(--rb-on-roast-2); }

/* beans */
.rb-beans { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-5); list-style: none; margin: 0; padding: 0; }
.rb-bean { background: var(--rb-paper); border: 1px solid var(--rb-line); border-radius: var(--radius-xl); padding: var(--space-6); display: flex; flex-direction: column; gap: var(--space-4); }
.rb-bean-top { display: flex; justify-content: space-between; align-items: center; font-family: var(--font-mono); font-size: var(--type-sm); color: var(--rb-ink-2); }
.rb-roastbar { display: flex; gap: 4px; }
.rb-roastbar span { width: 14px; height: 6px; border-radius: var(--radius-pill); background: var(--rb-line); }
.rb-roastbar span.on { background: var(--rb-roast-2); }
.rb-h3 { font-family: var(--font-display); font-size: var(--type-2xl); line-height: var(--lh-2xl); font-weight: var(--weight-semibold); margin: 0; }
.rb-notes { color: var(--rb-ink-2); margin: 0; }
.rb-bean-foot { margin-top: auto; display: flex; justify-content: space-between; align-items: center; padding-top: var(--space-4); border-top: 1px solid var(--rb-line); }
.rb-price { font-family: var(--font-mono); font-weight: var(--weight-medium); }
.rb-link { color: var(--rb-accent-text); font-weight: var(--weight-medium); text-decoration: underline; text-underline-offset: 3px; }

/* process */
.rb-steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-7); list-style: none; margin: 0; padding: 0; counter-reset: step; }
.rb-step { border-top: 1px solid var(--rb-line-roast); padding-top: var(--space-5); }
.rb-step-n { font-family: var(--font-mono); font-size: var(--type-sm); color: var(--rb-on-roast-2); }
.rb-step h3 { font-family: var(--font-display); font-size: var(--type-xl); line-height: var(--lh-xl); margin: var(--space-3) 0 var(--space-2); font-weight: var(--weight-semibold); }
.rb-step p { color: var(--rb-on-roast-2); margin: 0; }

/* subscription + visit */
.rb-split { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-6); }
.rb-card { border-radius: var(--radius-xl); padding: var(--space-7); display: flex; flex-direction: column; gap: var(--space-4); align-items: flex-start; }
.rb-card--accent { background: var(--rb-accent); color: var(--rb-on-roast); }
.rb-card--accent p { color: var(--rb-on-roast); }
.rb-card--line { border: 1px solid var(--rb-line); background: var(--rb-paper); }
.rb-card p { margin: 0; }
.rb-big { font-family: var(--font-display); font-size: 40px; line-height: 1; letter-spacing: -0.02em; font-weight: var(--weight-semibold); }
.rb-big small { font-size: var(--type-base); font-family: var(--font-body); font-weight: var(--weight-regular); letter-spacing: 0; }
.rb-hours { display: grid; grid-template-columns: auto 1fr; gap: var(--space-2) var(--space-6); margin: 0; font-family: var(--font-mono); font-size: var(--type-base); }
.rb-hours dt { color: var(--rb-ink-2); }
.rb-hours dd { margin: 0; }

/* footer */
.rb-foot { padding: var(--space-7) 0; display: flex; justify-content: space-between; gap: var(--space-5); flex-wrap: wrap; font-size: var(--type-sm); color: var(--rb-ink-2); border-top: 1px solid var(--rb-line); }
.rb-foot p { margin: 0; }

/* ── reflow (container, never vw) ──────────────────────────────────────────── */
@container (max-width: 1000px) {
  .rb-wrap { padding: 0 var(--space-6); }
  .rb-hero { grid-template-columns: 1fr; gap: var(--space-7); padding: 64px 0 80px; }
  .rb-plate { max-width: 420px; width: 100%; justify-self: center; }
  .rb-h1 { font-size: 60px; }
  .rb-beans { grid-template-columns: 1fr 1fr; }
  .rb-beans > :last-child { grid-column: 1 / -1; }
  .rb-steps { grid-template-columns: 1fr; gap: var(--space-5); }
  .rb-links { display: none; }
  .rb-section { padding: 72px 0; }
}
@container (max-width: 560px) {
  .rb-wrap { padding: 0 var(--space-5); }
  .rb-h1 { font-size: 42px; }
  .rb-h2 { font-size: 32px; }
  .rb-lead { font-size: var(--type-md); line-height: var(--lh-md); }
  .rb-head { flex-direction: column; align-items: flex-start; }
  .rb-beans, .rb-split { grid-template-columns: 1fr; }
  .rb-beans > :last-child { grid-column: auto; }
  .rb-stamp { width: 104px; height: 104px; right: 0; }
  .rb-stamp strong { font-size: 24px; }
  .rb-card { padding: var(--space-6); }
  .rb-nav .rb-btn { display: none; }
  .rb-section { padding: 56px 0; }
}

